// Prints a node and everything inside it, one line per node,
// indented two spaces per generation. Skips <script> tags and
// text nodes that are only spaces and line breaks.
function printTree(node, depth = 0) {
  const pad = "  ".repeat(depth);
  if (node.nodeType === Node.TEXT_NODE) {
    if (node.textContent.trim() !== "") {
      console.log(pad + JSON.stringify(node.textContent));
    }
    return;
  }
  if (node.nodeName === "SCRIPT") return;
  if (node.nodeType === Node.DOCUMENT_TYPE_NODE) {
    console.log(pad + "<!doctype " + node.name + ">");
    return;
  }
  if (node.nodeType === Node.DOCUMENT_NODE) {
    console.log(pad + "document");
  } else {
    let attrs = "";
    for (const a of node.attributes) {
      attrs += a.value === "" ? " " + a.name : " " + a.name + '="' + a.value + '"';
    }
    console.log(pad + "<" + node.localName + attrs + ">");
  }
  for (const child of node.childNodes) {
    printTree(child, depth + 1);
  }
}

js/usher-board.js.src:
const form = document.querySelector("#add-guest");
const input = document.querySelector("#guest");
const list = document.querySelector("#guests");
const status = document.querySelector("#status");

function say(message) {
  status.textContent = message;
  console.log(message);
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const name = input.value.trim();
  if (name === "") {
    say("Type a name first.");
    return;
  }
  const li = document.createElement("li");
  const seat = document.createElement("button");
  seat.textContent = name;
  seat.className = "seat";
  const gone = document.createElement("button");
  gone.textContent = "Remove";
  gone.className = "gone";
  li.append(seat, gone);
  list.append(li);
  input.value = "";
  say(name + " added. Guests: " + list.children.length);
});

list.addEventListener("click", (event) => {
  const li = event.target.parentNode;
  if (event.target.matches(".seat")) {
    li.classList.toggle("seated");
    const seated = li.classList.contains("seated");
    say(event.target.textContent + (seated ? " is seated." : " stood up."));
  }
  if (event.target.matches(".gone")) {
    li.remove();
    say("Removed. Guests: " + list.children.length);
  }
});
